import net.minecraftforge.common.ForgeConfigSpec;

@OnlyIn(value=Dist.CLIENT)
public interface AuthenticationHelper {
    public boolean valid();

    public void initialize(ForgeConfigSpec.ConfigValue<String> var1, ForgeConfigSpec.ConfigValue<String> var2, ForgeConfigSpec.EnumValue<AuthenticationProvider> var3);

    default public Screen getAvatarEditorScreen(Screen parentScreen) {
        return null;
    }

    public Status status();

    @OnlyIn(value=Dist.CLIENT)
    public static enum AuthenticationProvider {
        NULL("null"),
        DISCORD("discord"),
        PATREON("patreon");

        String signature;

        private AuthenticationProvider(String signature) {
            this.signature = signature;
        }

        public String toString() {
            return this.signature;
        }
    }

    @OnlyIn(value=Dist.CLIENT)
    public static enum Status {
        UNAUTHENTICATED,
        AUTHENTICATED,
        OFFLINE_MODE;

    }
}

